css:
.chart{display:grid;grid-template-columns:64px repeat(6,1fr);column-gap:0}
.years{display:grid;justify-items:end;padding-right:16px}
.years b{font-size:13px;align-self:start;padding-top:10px;font-weight:400}
.years i{display:block;width:0;height:0;border:6px solid transparent;
  border-top:9px solid #e2352c;margin:14px auto}
.col{background:#eaf4fb}          /* 縦罫でなく色帯で列を分ける */
.col:nth-child(3){background:#eaf7ee}
.col:nth-child(4){background:#fdf3e6}
